-- Uploaded images (media feature), ADR-0006. The files live in MediaStorage; this table holds their
-- metadata. Features that use media attach it (attached_at) and link it with their own join tables.
CREATE TABLE media (
    -- Random, generated by the service, so media URLs cannot be guessed.
    id           uuid        PRIMARY KEY,
    uploader_id  bigint      NOT NULL REFERENCES users (id),
    content_type varchar(16) NOT NULL CHECK (content_type IN ('image/jpeg', 'image/png', 'image/webp')),
    size_bytes   bigint      NOT NULL CHECK (size_bytes > 0),
    width        integer     NOT NULL CHECK (width > 0),
    height       integer     NOT NULL CHECK (height > 0),
    created_at   timestamptz NOT NULL,
    -- Null until a feature attaches the upload; the cleanup deletes old unattached uploads.
    attached_at  timestamptz
);

CREATE INDEX media_unattached_created_at ON media (created_at) WHERE attached_at IS NULL;
CREATE INDEX media_uploader_id_idx ON media (uploader_id);
